import { useState, useEffect, useCallback, useRef } from "react";
import { supabase } from "@/integrations/supabase/client";
import { searchCache, pushFeedsBulk } from "@/lib/localCache";

export type LiveSearchResult = {
  id: string;
  title: string;
  link: string;
  severity: string;
  source_name: string;
  category: string;
  published_at: string;
  excerpt?: string | null;
};

type Options = {
  debounceMs?: number;
  limit?: number;
  table?: string;
};

export function useLiveSearch(query: string, opts: Options = {}) {
  const { debounceMs = 350, limit = 8, table = "threat_items" } = opts;

  const [results, setResults]     = useState<LiveSearchResult[]>([]);
  const [loading, setLoading]     = useState(false);
  const [open, setOpen]           = useState(false);
  // "cache" = served from local Docker Redis  |  "supabase" = live DB query
  const [dataSource, setDataSource] = useState<"cache" | "supabase" | null>(null);
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const search = useCallback(async (q: string) => {
    if (!q.trim() || q.trim().length < 2) {
      setResults([]); setOpen(false); setLoading(false);
      return;
    }

    setLoading(true);
    setOpen(true);

    // ── 1. Try local Docker cache first (fast, no network round-trip) ────────
    const cached = await searchCache(q, { limit });
    if (cached.fromCache && cached.results.length > 0) {
      setResults(cached.results as LiveSearchResult[]);
      setOpen(true);
      setDataSource("cache");
      setLoading(false);
      return;
    }

    // ── 2. Fallback to Supabase ───────────────────────────────────────────────
    try {
      const { data, error } = await supabase
        .from(table)
        .select("id,title,link,severity,source_name,category,published_at,excerpt")
        .or(`title.ilike.%${q}%,excerpt.ilike.%${q}%,source_name.ilike.%${q}%`)
        .order("published_at", { ascending: false })
        .limit(limit);

      if (!error && data) {
        setResults(data as LiveSearchResult[]);
        setOpen(data.length > 0);
        setDataSource("supabase");

        // Fire-and-forget: populate cache so next search hits local Docker
        if (data.length > 0) {
          pushFeedsBulk(data).catch(() => {});
        }
      }
    } catch {
      // silent — live search must never break the UI
    } finally {
      setLoading(false);
    }
  }, [table, limit]);

  useEffect(() => {
    if (timerRef.current) clearTimeout(timerRef.current);
    if (!query.trim() || query.trim().length < 2) {
      setResults([]); setOpen(false); setLoading(false);
      return;
    }
    setLoading(true);
    timerRef.current = setTimeout(() => search(query), debounceMs);
    return () => { if (timerRef.current) clearTimeout(timerRef.current); };
  }, [query, debounceMs, search]);

  const clear = () => {
    setResults([]); setOpen(false); setLoading(false); setDataSource(null);
  };

  return { results, loading, open, setOpen, clear, dataSource };
}
