import { useRef } from "react";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Search, Loader2, ExternalLink, X } from "lucide-react";
import { useLiveSearch } from "@/hooks/useLiveSearch";

const SEV_BADGE: Record<string, string> = {
  critical: "bg-red-500/15 text-red-400 border-red-500/40",
  high:     "bg-orange-400/15 text-orange-400 border-orange-400/40",
  medium:   "bg-blue-400/15 text-blue-400 border-blue-400/40",
  low:      "bg-green-500/15 text-green-400 border-green-500/40",
};

function timeAgo(iso: string) {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

type Props = {
  value: string;
  onChange: (v: string) => void;
  placeholder?: string;
  className?: string;
  debounceMs?: number;
  limit?: number;
};

export function LiveSearchInput({
  value, onChange, placeholder = "Search…", className = "", debounceMs = 350, limit = 8,
}: Props) {
  const wrapRef = useRef<HTMLDivElement>(null);
  const { results, loading, open, setOpen, clear } = useLiveSearch(value, { debounceMs, limit });

  const handleBlur = () => {
    // Delay so clicks on dropdown items register first
    setTimeout(() => setOpen(false), 200);
  };

  return (
    <div ref={wrapRef} className={`relative ${className}`}>
      {/* Input */}
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
        <Input
          value={value}
          onChange={e => onChange(e.target.value)}
          onFocus={() => { if (results.length > 0) setOpen(true); }}
          onBlur={handleBlur}
          placeholder={placeholder}
          className={`pl-9 pr-8 ${loading ? "pr-14" : ""}`}
        />
        {loading && (
          <Loader2 className="absolute right-8 top-1/2 -translate-y-1/2 h-3.5 w-3.5 animate-spin text-muted-foreground" />
        )}
        {value && (
          <button
            onMouseDown={e => { e.preventDefault(); onChange(""); clear(); }}
            className="absolute right-2.5 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
          >
            <X className="h-3.5 w-3.5" />
          </button>
        )}
      </div>

      {/* Dropdown */}
      {open && results.length > 0 && (
        <div className="absolute z-50 mt-1 w-full rounded-lg border border-border/60 bg-card/95 backdrop-blur shadow-xl overflow-hidden">
          <div className="px-3 py-1.5 border-b border-border/40 flex items-center justify-between">
            <span className="text-[10px] uppercase tracking-widest text-muted-foreground">
              Live results · {results.length} found
            </span>
            <button onMouseDown={e => { e.preventDefault(); setOpen(false); }} className="text-muted-foreground hover:text-foreground">
              <X className="h-3 w-3" />
            </button>
          </div>
          <ul className="max-h-72 overflow-y-auto divide-y divide-border/30">
            {results.map(r => (
              <li key={r.id}>
                <a
                  href={r.link}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="flex items-start gap-2 px-3 py-2.5 hover:bg-accent/50 transition-colors group"
                >
                  <Badge className={`border text-[9px] shrink-0 mt-0.5 ${SEV_BADGE[r.severity] || ""}`}>
                    {r.severity}
                  </Badge>
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-medium leading-snug truncate group-hover:text-primary transition-colors">
                      {r.title}
                    </p>
                    <p className="text-[10px] text-muted-foreground mt-0.5 truncate">
                      {r.source_name} · {timeAgo(r.published_at)}
                    </p>
                  </div>
                  <ExternalLink className="h-3 w-3 text-muted-foreground shrink-0 mt-0.5 opacity-0 group-hover:opacity-100 transition-opacity" />
                </a>
              </li>
            ))}
          </ul>
          <div className="px-3 py-1.5 border-t border-border/40 text-[10px] text-muted-foreground">
            Press Enter to search all · Esc to close
          </div>
        </div>
      )}
    </div>
  );
}
